use verus::*;

verus! {

  // Given a non-empty vector of integer vectors `seq`, 
  // check if all inner vectors have the same length.
  //
  // Requires:
  // - seq.len() > 0 (non-empty outer vector)
  //
  // Ensures:
  // - result is true if and only if all inner vectors have the same length,
  //   i.e., for every pair of indices i,j in 0..seq.len(), seq[i].len() == seq[j].len()
  fn all_sequence_equal_length(seq: &Vec<Vec<i32>>) -> (result: bool)
    requires seq.len() > 0
    ensures
      result == forall|i: usize, j: usize|
        i < seq.len() && j < seq.len() ==> seq[i].len() == seq[j].len()
  {
    // store the length of the first inner vector to compare to others
    let first_len = seq.index(0).len();

    // we iterate over all inner vectors and check if their length equals first_len
    // if any does not match, return false immediately
    let mut i: usize = 1;
    while i < seq.len()
      invariant i <= seq.len()
      invariant forall|k: usize| k < i ==> seq[k].len() == first_len
      decreases seq.len() - i
    {
      if seq.index(i).len() != first_len {
        return false;
      }
      i += 1;
    }

    // all inner vectors have the same length as the first, return true
    true
  }

}